              if all(out[r][x] for x in (c,c+1,c+2))),None)
    if seed is None:
        return out
    r,c=seed
    motif=out[r][c:c+3]
    markers=[(y,x,out[y][x]) for y in range(h) for x in range(w)
             if out[y][x] and (y,x) not in ((r,c),(r,c+1),(r,c+2))]
    # For each motif color, extend its vertical stripe to its endpoint(s).
    # If it has no endpoint, its stripe spans the whole grid.
    for i,color in enumerate(motif):
        matching=[(y,x) for y,x,v in markers if v==color]
        if matching:
            lo=min([r]+[y for y,x in matching])
            hi=max([r]+[y for y,x in matching])
        else:
            lo,hi=0,h-1
        for y in range(lo,hi+1):
            out[y][c+i]=color
    # Each isolated marker joins horizontally to its corresponding motif stripe.
    for y,x,v in markers:
        i=motif.index(v)
        for xx in range(min(x,c+i),max(x,c+i)+1):
            out[y][xx]=v
    return out

